// Get Record ID from current item
const recordId = $input.first().json.id;

// Get the transcript directly
const inputText = $('Process Transcript1').first().json.transcript;

if (!inputText || inputText.length === 0) {
  throw new Error('No transcript text to chunk');
}

// Chunking configuration
const maxChunkSize = 20000;
const minChunkSize = Math.floor(maxChunkSize * 0.25);

let chunks = [];
let chunkOrder = 1;

// Add chunk with Record ID and order
function addChunk(text) {
  chunks.push({
    recordId: recordId,
    order: chunkOrder,
    text: text
  });
  chunkOrder++;
}

// Find last period in text for clean sentence breaks
function findLastPeriodIndex(text, startFromIndex) {
  for (let i = startFromIndex; i >= 0; i--) {
    if (text[i] === '.') {
      return i + 1;
    }
  }
  return -1;
}

// Main chunking logic
let startIndex = 0;
while (startIndex < inputText.length) {
  let endIndex = Math.min(startIndex + maxChunkSize, inputText.length);
  let chunkText = inputText.slice(startIndex, endIndex);

  // If not at the end, try to break at a sentence
  if (endIndex < inputText.length) {
    let lastPeriodIndex = findLastPeriodIndex(chunkText, chunkText.length - 1);
    if (lastPeriodIndex !== -1) {
      endIndex = startIndex + lastPeriodIndex;
      chunkText = inputText.slice(startIndex, endIndex);
    }

    // Avoid tiny final chunks
    let nextChunkSize = Math.min(maxChunkSize, inputText.length - endIndex);
    if (nextChunkSize < minChunkSize) {
      endIndex = Math.min(endIndex + nextChunkSize, inputText.length);
      chunkText = inputText.slice(startIndex, endIndex);
    }
  }

  addChunk(chunkText);
  startIndex = endIndex;
}

// Return each chunk as a separate item
return chunks.map(chunk => ({
  json: chunk
}));

// Get the first item from Apify response
const data = $input.first().json;

// Compile transcript segments into full text
const fullTranscript = data.transcript
  .map(segment => segment.text)
  .join(' ');

// Return everything with correct fields
return {
  // Video identifiers
  videoId: data.video_id,
  url: data.url,

  // Video metadata
  title: data.title,
  description: data.description,
  thumbnail: data.thumbnail,
  publishedAt: data.published_at,
  duration: data.duration_seconds,

  // Engagement stats
  viewCount: data.view_count,
  likeCount: data.like_count,
  commentCount: data.comment_count,

  // Channel info
  channelId: data.channel_id,
  channelName: data.channel_name,
  subscriberCount: data.subscriber_count,

  // Transcript data
  language: data.language,
  isAutoGenerated: data.is_auto_generated,
  transcript: fullTranscript
};

// ============================================================
// n8n Code Node — Social Media Post Categorizer
// Input:  $input.first().json  (Gemini output with platform posts)
// Output: Individual fields per platform, ready for social media nodes
// ============================================================

// --- 1. Grab raw input from previous node --------------------
const raw = $input.first().json.content.parts[0].text
  $input.first().json.text ??
  $input.first().json.output ??
  $input.first().json.content ??
  $input.first().json.message ??
  $input.first().json.response ??
  JSON.stringify($input.first().json);

if (!raw) throw new Error("No input found. Check the key name in $input.first().json");

// --- 2. Clean and parse JSON ---------------------------------
const cleaned = raw
  .replace(/```json\s*/gi, "")
  .replace(/```\s*/gi, "")
  .trim();

let posts;
try {
  posts = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Failed to parse JSON: " + e.message + "\nInput preview: " + raw.slice(0, 300));
}

if (!Array.isArray(posts)) throw new Error("Expected an array of platform posts.");

// --- 3. Normalize platform names -----------------------------
const normalize = (str) =>
  str
    .toUpperCase()
    .replace(/\s+/g, "")
    .replace("TWITTER/X", "TWITTER")
    .replace("TWITTERX", "TWITTER")
    .replace("X(TWITTER)", "TWITTER");

// --- 4. Map posts to a lookup object -------------------------
const postMap = {};
for (const item of posts) {
  const platform = normalize(item.platform ?? item.Platform ?? "");
  const post = item.post ?? item.Post ?? item.content ?? item.Content ?? "";
  if (platform && post) {
    postMap[platform] = post;
  }
}

// --- 5. Build clean output -----------------------------------
const linkedin  = postMap["LINKEDIN"]  ?? null;
const instagram = postMap["INSTAGRAM"] ?? null;
const twitter   = postMap["TWITTER"]   ?? null;
const facebook  = postMap["FACEBOOK"]  ?? null;

// --- 6. Warn about missing platforms -------------------------
const missing = ["LINKEDIN", "INSTAGRAM", "TWITTER", "FACEBOOK"].filter(
  (p) => !postMap[p]
);

return [
  {
    json: {
      linkedin,
      instagram,
      twitter,
      facebook,
      ...(missing.length ? { warning: `Missing platforms: ${missing.join(", ")}` } : {}),
    },
  },
];

// ============================================================
// n8n Code Node — Battlecard JSON to Markdown Cleaner
// Input:  $input.first().json  (the raw text from previous node)
// Output: { markdown: "..." }
// ============================================================

// --- 1. Grab the raw text from the previous n8n node ----------
const rawText = $input.first().json.content.parts[0].text // adjust key if needed
  ?? $input.first().json.output
  ?? $input.first().json.content
  ?? $input.first().json.message;

if (!rawText) throw new Error("No input text found. Check the key name in $input.first().json");

// --- 2. Strip any wrapping code fences or extra whitespace ----
const cleaned = rawText
  .replace(/```json\s*/gi, "")
  .replace(/```\s*/gi, "")
  .trim();

// --- 3. Parse JSON -------------------------------------------
let data;
try {
  data = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Failed to parse JSON: " + e.message + "\nRaw input was:\n" + rawText.slice(0, 300));
}

// --- 4. Helper: safe array getter ----------------------------
const getArray = (obj, ...keys) => {
  for (const key of keys) {
    if (Array.isArray(obj[key])) return obj[key];
  }
  return [];
};

// --- 5. Build Markdown sections ------------------------------
const lines = [];

// ── Product Feature Highlights ──
const features = getArray(data, "Product Feature Highlights", "features", "Features");
if (features.length) {
  lines.push("**Product Feature Highlights**");
  features.forEach((item, i) => {
    const name = item.Feature ?? item.feature ?? item.name ?? item.Name ?? `Feature ${i + 1}`;
    const desc = item.Description ?? item.description ?? item.detail ?? "";
    lines.push(`- ${name}: ${desc}`);
  });
  lines.push("");
}

// ── Objection-Handling Tips ──
const objections = getArray(data, "Objection-Handling Tips", "Objections", "objections");
if (objections.length) {
  lines.push("**Objection-Handling Tips**");
  objections.forEach(item => {
    const objection = item.Objection ?? item.objection ?? item.concern ?? item.Concern ?? "";
    const response  = item.Response  ?? item.response  ?? item.answer  ?? item.Answer  ?? "";
    lines.push(`- **Objection**: ${objection}`);
    lines.push(`  **Response**: ${response}`);
  });
  lines.push("");
}

// ── Unique Selling Points ──
const usps = getArray(data, "Unique Selling Points", "USPs", "usps");
if (usps.length) {
  lines.push("**Unique Selling Points**");
  usps.forEach((item, i) => {
    const usp  = item.USP  ?? item.usp  ?? item.title ?? item.Title ?? `USP ${i + 1}`;
    const desc = item.Description ?? item.description ?? item.detail ?? "";
    lines.push(`- ${usp}: ${desc}`);
  });
  lines.push("");
}

// ── Key Metrics ──
const metrics = getArray(data, "Key Metrics", "Metrics", "metrics", "Statistics", "statistics");
if (metrics.length) {
  lines.push("**Key Metrics**");
  metrics.forEach((item, i) => {
    const metric  = item.Metric  ?? item.metric  ?? item.name    ?? item.Name    ?? `Metric ${i + 1}`;
    const details = item.Details ?? item.details ?? item.value   ?? item.Value   ?? "";
    lines.push(`- ${metric}: ${details}`);
  });
  lines.push("");
}

// --- 6. Build final output -----------------------------------
const NL = "\n";
const markdown = lines.join(NL);

// plainText: same content but guaranteed real newlines (for nodes that don't render markdown)
const plainText = markdown.replace(/\*\*/g, "");  // strip ** bold markers for plain text

return [{ json: { markdown, plainText } }];

// ============================================================
// n8n Code Node — Markdown / Escaped Text to Plain Text
// Input:  $input.first().json  (any field containing markdown or escaped text)
// Output: { plainText: "..." }
// ============================================================

// --- 1. Grab raw input ---------------------------------------
const raw = $input.first().json.output
  $input.first().json.text ??
  $input.first().json.output ??
  $input.first().json.content ??
  $input.first().json.message ??
  $input.first().json.response ??
  $input.first().json.markdown ??
  JSON.stringify($input.first().json);

if (!raw) throw new Error("No input found. Check the key name in $input.first().json");

// --- 2. Convert to plain text --------------------------------
let plain = raw

  // Fix escaped newlines and tabs first
  .replace(/\\n/g, "\n")
  .replace(/\\t/g, "\t")
  .replace(/\\r/g, "")

  // Remove markdown headings (##, ###, etc.)
  .replace(/^#{1,6}\s+/gm, "")

  // Remove bold/italic (**text**, __text__, *text*, _text_)
  .replace(/\*\*(.+?)\*\*/g, "$1")
  .replace(/__(.+?)__/g, "$1")
  .replace(/\*(.+?)\*/g, "$1")
  .replace(/_(.+?)_/g, "$1")

  // Remove inline code (`code`)
  .replace(/`(.+?)`/g, "$1")

  // Remove code blocks (```...```)
  .replace(/```[\s\S]*?```/g, "")

  // Convert markdown bullet points (*, -, •) to plain dashes
  .replace(/^[\*\-•]\s+/gm, "- ")

  // Remove blockquotes (> text)
  .replace(/^>\s+/gm, "")

  // Remove horizontal rules (---, ___, ***)
  .replace(/^(-{3,}|_{3,}|\*{3,})$/gm, "")

  // Remove markdown links [text](url) → just keep text
  .replace(/\[([^\]]+)\]\([^\)]+\)/g, "$1")

  // Remove image markdown ![alt](url)
  .replace(/!\[([^\]]*)\]\([^\)]+\)/g, "")

  // Remove HTML tags if any slipped in
  .replace(/<[^>]+>/g, "")

  // Collapse 3+ consecutive newlines into 2
  .replace(/\n{3,}/g, "\n\n")

  // Trim leading/trailing whitespace
  .trim();

// --- 3. Return output ----------------------------------------
return [{ json: { plainText: plain } }];
